class Fibonacci{
	private long mod;
	private Map<Long, Long> calculatedNumbers;

	public Fibonacci(long mod){
		calculatedNumbers = new TreeMap<>();
		calculatedNumbers.put(0l, 1l);
		calculatedNumbers.put(1l, 1l);
		this.mod = mod;
	}

	public long fib(long n){
		if(calculatedNumbers.containsKey(n)) return calculatedNumbers.get(n);

		long k = n/2, res;
		if(n%2 == 0){
			res = (fib(k)*fib(k)+fib(k-1)*fib(k-1))%mod;
		}else{
			res = (fib(k)*fib(k+1)+fib(k-1)*fib(k))%mod;
		}
		calculatedNumbers.put(n, res);
		return res;
	}
}

class Exponentation{
	//a^b mod m
	public static long calc(long a, long b, long m){
		if(b == 0) return 1;
		if(b == 1) return a;
		if(b%2 == 0) return calc(a*a%m, b/2, m);
		else return a*calc((a*a%m), (b-1)/2, m)%m;
	}
}

class Solver{
	long n, k, l, MOD;

	void read(InputReader in){
		n = in.nextLong();
		k = in.nextLong();
		l = in.nextLong();
		MOD = in.nextLong();
	}

	public void solve(InputReader in, PrintWriter out){
		read(in);
		if(l != 64 && (1l << l)-1 < k){
			out.println(0);
			return;
		}

		long zeroPos = new Fibonacci(MOD).fib(n+1);
		long onePos = Exponentation.calc(2, n, MOD)-zeroPos;
		while(onePos < 0) onePos += MOD;

		long res = 1;
		for(int i=0; i<l; i++){
			if((k & (1l << i)) != 0) res *= onePos;
			else res *= zeroPos;
			res %= MOD;
		}
		out.println(res%MOD);
	}
}

